import type { NextConfig } from "next";
import { withSerwist } from "@serwist/turbopack";

/*
 * Why `cacheComponents` (and `partialPrefetching`, which requires it) is OFF:
 *
 * The service worker is generated by Serwist's route handler (app/serwist/[path]/route.ts),
 * which relies on `dynamic = "force-static"` + `revalidate = false` to be built once at
 * `next build` and never again. Cache Components forbids those segment configs. The workaround
 * (wrapping the bundle in `use cache`) inherits a cache lifetime, so after 15 minutes the server
 * re-ran Serwist at runtime (glob + hash + esbuild) and froze the event loop for 7–10 s per file.
 * No `cacheLife` profile disables revalidation, and on Vercel the re-run would happen in a
 * function without `.next/static`, producing a worker with an empty precache.
 *
 * Future alternative that would let us turn the flag back on: Serwist's "configurator mode"
 * (`@serwist/next/config` + running `serwist build` after `next build`), which generates the
 * worker as a static file outside any route handler.
 * Regression test: tests/e2e/shell.spec.ts ("service worker é estático…").
 */
const nextConfig: NextConfig = {
  turbopack: {
    rules: {
      // Only the file that uses Tailwind: matching every "*.css" turned CSS Modules into plain CSS
      // (empty class names).
      "globals.css": {
        loaders: ["@tailwindcss/turbopack"],
        as: "*.css",
      },
    },
  },
  async redirects() {
    // Signed-out and new users are sent on to /entrar or /boas-vindas on the device (AuthGate).
    return [{ source: "/", destination: "/inicio", permanent: false }];
  },
};

export default withSerwist(nextConfig);
